<?php require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/config/db.php';if(empty($_SESSION['user_id'])){header('Location: auth/login.php');exit;}$month=max(1,min(12,(int)($_GET['month']??date('n'))));$year=(int)($_GET['year']??date('Y'));$first=mktime(0,0,0,$month,1,$year);$days=(int)date('t',$first);$start=(int)date('w',$first);$rows=[];try{$p=db();$q=$p->prepare("SELECT booking_date,start_time,subject_id,status FROM bookings WHERE ".(($_SESSION['user_role']??'')==='tutor'?'tutor_id=(SELECT id FROM tutors WHERE user_id=?)':'student_id=?')." AND booking_date BETWEEN ? AND ? ORDER BY booking_date");$q->execute([$_SESSION['user_id'],date('Y-m-01',$first),date('Y-m-t',$first)]);foreach($q as $r)$rows[$r['booking_date']][]=$r;}catch(Throwable $e){}$pageTitle='Monthly calendar';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="container py-5"><div class="d-flex justify-content-between"><h1 class="h2"><?=date('F Y',$first)?></h1><a class="btn btn-outline-brand" href="schedule.php">Weekly view</a></div><table class="table table-bordered calendar-table mt-3"><thead><tr><?php foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $d):?><th><?=$d?></th><?php endforeach;?></tr></thead><tbody><tr><?php for($i=0;$i<$start;$i++):?><td></td><?php endfor;for($day=1;$day<=$days;$day++):$date=sprintf('%04d-%02d-%02d',$year,$month,$day);?><td><strong><?=$day?></strong><?php foreach($rows[$date]??[] as $r):?><div class="small mt-2 p-1 rounded bg-success-subtle"><?=e($r['start_time'])?><br><?=e($r['status'])?></div><?php endforeach;?></td><?php if(($start+$day)%7===0&&$day<$days):?></tr><tr><?php endif;endfor;for($i=($start+$days)%7;$i>0&&$i<7;$i++):?><td></td><?php endfor;?></tr></tbody></table></main><?php require __DIR__.'/includes/footer.php';?>
